    getRules: getRules,
    saveRules: saveRules,
    getRuleById: getRuleById,
    getNextRuleId: getNextRuleId,
    getRulesForStore: getRulesForStore,
    deleteRuleById: deleteRuleById,
    ruleHasSalesPool: ruleHasSalesPool,
