        var empAmounts = emps.map(function(emp) { return +(otResult.receivedByName && otResult.receivedByName[emp] || 0); });
        var empPcts = empAmounts.map(function(amount) { return roleAmount > 0 ? roundPct(amount / roleAmount * 100) : 0; });
        var sectionId = 'detailOtSec_' + ridSafe + '_r' + ri;
