      if (Array.isArray(cond.shift) && cond.shift.length) parts.push('班次: ' + detailFormatShiftNames(cond.shift));
      if (Array.isArray(cond.weekdays) && cond.weekdays.length) parts.push('周期: ' + detailFormatWeekdays(cond.weekdays));
      return parts.join(' | ');
