        var distNames2 = (window.ruleData && ruleData.distNames) || { average: '按员工数量平均分配', hours: '按工作时长占比分配', orders: '按订单占比分配' };
        var poolTypeNames2 = (window.ruleData && ruleData.poolTypeNames) || { sales: '销售额', personal_sales: '按个人销售额', tips: '小费', surcharge: '加收服务费', manual: '手动上报小费', custom: '自定义小费' };
        var store = document.getElementById('storeSelect');
